import{_ as p,a0 as d,w as o,s as r,I as e,x as i,a1 as n,A as a,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何根据文件权限查找文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何根据文件权限查找文件 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何根据文件权限查找文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何根据文件权限查找文件 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171207 How To Find Files Based On their Permissions","title":"如何根据文件权限查找文件","tag":"201801","desc":""},"relativePath":"201801/20171207 How To Find Files Based On their Permissions.md","filePath":"[post].md"}'),h={name:"201801/20171207 How To Find Files Based On their Permissions.md"};function g(c,s,k,u,f,b){const t=d("Link");return o(),r("div",null,[s[22]||(s[22]=e("h1",{id:"如何根据文件权限查找文件",tabindex:"-1"},[i("如何根据文件权限查找文件 "),e("a",{class:"header-anchor",href:"#如何根据文件权限查找文件","aria-label":"Permalink to “如何根据文件权限查找文件”"},"​")],-1)),s[23]||(s[23]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/12/Find-Files-Based-On-their-Permissions-720x340.png",alt:""})],-1)),e("p",null,[s[1]||(s[1]=i("在 Linux 中查找文件并不是什么大问题。市面上也有很多可靠的自由开源的可视化查找工具。但对我而言，查找文件，用命令行的方式会更快更简单。我们已经知道 ",-1)),n(t,{href:"https://www.ostechnix.com/find-sort-files-based-access-modification-date-time-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("如何根据访问和修改文件的时间寻找或整理文件",-1)])]),_:1}),s[2]||(s[2]=i("。今天，在基于 Unix 的操作系统中，我们将见识如何通过权限查找文件。",-1))]),s[24]||(s[24]=l(`<p>本段教程中，我将创建三个文件名为 <code>file1</code>，<code>file2</code> 和 <code>file3</code> 分别赋予 <code>777</code>，<code>766</code> 和 <code>655</code> 文件权限，并分别置于名为 <code>ostechnix</code> 的文件夹中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir ostechnix &amp;&amp; cd ostechnix/</span></span>
<span class="line"><span>install -b -m 777 /dev/null file1</span></span>
<span class="line"><span>install -b -m 766 /dev/null file2</span></span>
<span class="line"><span>install -b -m 655 /dev/null file3</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-1-1.png" alt=""></p><p>现在，让我们通过权限来查找一下文件。</p><h3 id="根据权限查找文件" tabindex="-1">根据权限查找文件 <a class="header-anchor" href="#根据权限查找文件" aria-label="Permalink to “根据权限查找文件”">​</a></h3><p>根据权限查找文件最具代表性的语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm mode</span></span></code></pre></div><p>mode 可以是代表权限的八进制数字（777、666 …）也可以是权限符号（u=x，a=r+x）。</p><p>在深入之前，我们就以下三点详细说明 mode 参数。</p><ol><li>如果我们不指定任何参数前缀，它将会寻找<strong>具体</strong>权限的文件。</li><li>如果我们使用 <code>-</code> 参数前缀， 寻找到的文件至少拥有 mode 所述的权限，而不是具体的权限（大于或等于此权限的文件都会被查找出来）。</li><li>如果我们使用 <code>/</code> 参数前缀，那么所有者、组或者其他人任意一个应当享有此文件的权限。</li></ol><p>为了让你更好的理解，让我举些例子。</p><p>首先，我们将要看到基于数字权限查找文件。</p><h3 id="基于数字-八进制-权限查找文件" tabindex="-1">基于数字（八进制）权限查找文件 <a class="header-anchor" href="#基于数字-八进制-权限查找文件" aria-label="Permalink to “基于数字（八进制）权限查找文件”">​</a></h3><p>让我们运行下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm 777</span></span></code></pre></div><p>这条命令将会查找到当前目录权限为<strong>确切为 777</strong> 权限的文件。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-2.png" alt="1"></p><p>如你看见的屏幕输出，file1 是唯一一个拥有<strong>确切为 777 权限</strong>的文件。</p><p>现在，让我们使用 <code>-</code> 参数前缀，看看会发生什么。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -766</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-3.png" alt=""></p><p>如你所见，命令行上显示两个文件。我们给 file2 设置了 766 权限，但是命令行显示两个文件，什么鬼？因为，我们设置了 <code>-</code> 参数前缀。它意味着这条命令将在所有文件中查找文件所有者的“读/写/执行”权限，文件用户组的“读/写”权限和其他用户的“读/写”权限。本例中，file1 和 file2 都符合要求。换句话说，文件并不一样要求时确切的 766 权限。它将会显示任何属于（高于）此权限的文件 。</p><p>然后，让我们使用 <code>/</code> 参数前置，看看会发生什么。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm /222</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-6.png" alt=""></p><p>上述命令将会查找某些人（要么是所有者、用户组，要么是其他人）拥有写权限的文件。这里有另外一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm /220</span></span></code></pre></div><p>这条命令会查找所有者或用户组中拥有写权限的文件。这意味着匹配所有者和用户组任一可写的文件，而其他人的权限随意。</p><p>如果你使用 <code>-</code> 前缀运行相同的命令，你只会看到所有者和用户组都拥有写权限的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -220</span></span></code></pre></div><p>下面的截图会告诉你这两个参数前缀的不同。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-7.png" alt=""></p><p>如我之前说过的一样，我们也可以使用符号表示文件权限。</p><p>请阅读：</p>`,34)),e("ul",null,[e("li",null,[n(t,{href:"https://www.ostechnix.com/how-to-find-largest-and-smallest-directories-and-files-in-linux/"},{default:a(()=>[...s[3]||(s[3]=[i("如何在 Linux 中找到最大和最小的目录和文件",-1)])]),_:1})]),e("li",null,[n(t,{href:"https://www.ostechnix.com/find-oldest-file-directory-tree-linux/"},{default:a(()=>[...s[4]||(s[4]=[i("如何在 Linux 的目录树中找到最老的文件",-1)])]),_:1})]),e("li",null,[n(t,{href:"https://www.ostechnix.com/find-files-bigger-smaller-x-size-linux/"},{default:a(()=>[...s[5]||(s[5]=[i("如何在 Linux 中找到超过或小于某个大小的文件",-1)])]),_:1})])]),s[25]||(s[25]=l(`<h3 id="基于符号的文件权限查找文件" tabindex="-1">基于符号的文件权限查找文件 <a class="header-anchor" href="#基于符号的文件权限查找文件" aria-label="Permalink to “基于符号的文件权限查找文件”">​</a></h3><p>在下面的例子中，我们使用例如 <code>u</code>（所有者）、<code>g</code>（用户组） 和 <code>o</code>（其他） 的符号表示法。我们也可以使用字母 <code>a</code> 代表上述三种类型。我们可以通过特指的 <code>r</code> （读）、 <code>w</code> （写）、 <code>x</code> （执行）分别代表它们的权限。</p><p>例如，寻找用户组中拥有 <code>写</code> 权限的文件，执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -g=w</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/12/find-files-8.png" alt=""></p><p>上面的例子中，file1 和 file2 都拥有 <code>写</code> 权限。请注意，你可以等效使用 <code>=</code> 或 <code>+</code> 两种符号标识。例如，下列两行相同效果的代码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -g=w</span></span>
<span class="line"><span>find -perm -g+w</span></span></code></pre></div><p>查找文件所有者中拥有写权限的文件，执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -u=w</span></span></code></pre></div><p>查找所有用户中拥有写权限的文件，执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -a=w</span></span></code></pre></div><p>查找所有者和用户组中同时拥有写权限的文件，执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm -g+w,u+w</span></span></code></pre></div><p>上述命令等效与 <code>find -perm -220</code>。</p><p>查找所有者或用户组中拥有写权限的文件，执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm /u+w,g+w</span></span></code></pre></div><p>或者,</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find -perm /u=w,g=w</span></span></code></pre></div><p>上述命令等效于 <code>find -perm /220</code>。</p><p>更多详情，参照 man 手册。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man find</span></span></code></pre></div>`,21)),e("p",null,[s[7]||(s[7]=i("了解更多简化案例或其他 Linux 命令，查看",-1)),n(t,{href:"https://www.ostechnix.com/3-good-alternatives-man-pages-every-linux-user-know/"},{default:a(()=>[...s[6]||(s[6]=[i("man 手册",-1)])]),_:1}),s[8]||(s[8]=i("。",-1))]),s[26]||(s[26]=e("p",null,"然后，这就是所有的内容。希望这个教程有用。更多干货，敬请关注。",-1)),s[27]||(s[27]=e("p",null,"干杯！",-1)),s[28]||(s[28]=e("hr",null,null,-1)),e("p",null,[s[10]||(s[10]=i("via: ",-1)),n(t,{href:"https://www.ostechnix.com/find-files-based-permissions/"},{default:a(()=>[...s[9]||(s[9]=[i("https://www.ostechnix.com/find-files-based-permissions/",-1)])]),_:1})]),e("p",null,[s[14]||(s[14]=i("作者：",-1)),n(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[11]||(s[11]=[i("SK",-1)])]),_:1}),s[15]||(s[15]=i(" 译者：",-1)),n(t,{href:"https://github.com/CYLeft"},{default:a(()=>[...s[12]||(s[12]=[i("CYLeft",-1)])]),_:1}),s[16]||(s[16]=i(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[13]||(s[13]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[19]||(s[19]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[17]||(s[17]=[i("LCTT",-1)])]),_:1}),s[20]||(s[20]=i(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...s[18]||(s[18]=[i("Linux中国",-1)])]),_:1}),s[21]||(s[21]=i(" 荣誉推出",-1))])])}const C=p(h,[["render",g]]);export{x as __pageData,C as default};
